import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { FiMapPin, FiPhone, FiUser, FiX, FiEye } from 'react-icons/fi';

const ProductModal = ({ product, isOpen, onClose }) => {
    const { user } = useAuth();
    const [showContact, setShowContact] = useState(false);
    const [currentPhotoIndex, setCurrentPhotoIndex] = useState(0);

    useEffect(() => {
        const handleEsc = (e) => {
            if (e.key === 'Escape') onClose();
        };
        if (isOpen) {
            document.body.style.overflow = 'hidden';
            window.addEventListener('keydown', handleEsc);
        }
        return () => {
            document.body.style.overflow = 'unset';
            window.removeEventListener('keydown', handleEsc);
        };
    }, [isOpen, onClose]);

    if (!isOpen || !product) return null;

    const getCategoryIcon = (category) => {
        const icons = { telemovel: '📱', laptop: '💻', console: '🎮', tablet: '📟' };
        return icons[category] || '📦';
    };

    const getContactMethodIcon = (method) => {
        if (method === 'whatsapp') return '💚 WhatsApp';
        if (method === 'call') return '📞 Ligação';
        return '💚 WhatsApp / 📞 Ligação';
    };

    const handleBackdropClick = (e) => {
        if (e.target === e.currentTarget) onClose();
    };

    const isOwner = user && product.sellerId === user.id;

    return (
        <div 
            className="fixed inset-0 bg-black bg-opacity-50 backdrop-blur-sm flex items-center justify-center z-[1000] p-4"
            onClick={handleBackdropClick}
        >
            <div className="bg-white rounded-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto shadow-2xl animate-fadeInUp">
                {/* Cabeçalho */}
                <div className="sticky top-0 bg-white border-b p-4 flex justify-between items-center rounded-t-2xl">
                    <h2 className="text-lg font-semibold text-gray-800">Detalhes do Produto</h2>
                    <button 
                        onClick={onClose}
                        className="p-2 hover:bg-gray-100 rounded-full transition"
                    >
                        <FiX size={20} />
                    </button>
                </div>

                {/* Conteúdo */}
                <div className="p-5">
                    {/* Imagem */}
                    <div className="bg-gray-100 rounded-xl p-4 flex justify-center items-center mb-4 h-64">
                        {product.photos && product.photos[0] ? (
                            <img 
                                src={`http://localhost:3001${product.photos[currentPhotoIndex]}`} 
                                alt={product.title} 
                                className="max-w-full max-h-full object-contain" 
                            />
                        ) : (
                            <div className="text-6xl">{getCategoryIcon(product.category)}</div>
                        )}
                    </div>

                    {/* Miniaturas */}
                    {product.photos && product.photos.length > 1 && (
                        <div className="flex gap-2 mb-5 overflow-x-auto pb-2">
                            {product.photos.map((photo, idx) => (
                                <button
                                    key={idx}
                                    onClick={() => setCurrentPhotoIndex(idx)}
                                    className={`w-14 h-14 rounded-lg overflow-hidden border-2 flex-shrink-0 ${
                                        currentPhotoIndex === idx ? 'border-blue-500' : 'border-gray-200'
                                    }`}
                                >
                                    <img src={`http://localhost:3001${photo}`} alt="" className="w-full h-full object-cover" />
                                </button>
                            ))}
                        </div>
                    )}

                    {/* Título */}
                    <h3 className="text-xl font-bold text-gray-800 mb-1">{product.title}</h3>
                    
                    {/* Estado */}
                    <div className="flex items-center gap-2 mb-3">
                        <span className={`px-2 py-1 rounded-full text-xs font-semibold ${
                            product.condition === 'novo' ? 'bg-green-100 text-green-600' : 'bg-yellow-100 text-yellow-600'
                        }`}>
                            {product.condition === 'novo' ? 'Novo' : 'Semi-novo'}
                        </span>
                        <span className="text-xs text-gray-400">{product.category}</span>
                    </div>

                    {/* Preço */}
                    <p className="text-2xl font-bold text-blue-600 mb-4">
                        {product.price.toLocaleString()} Kz
                    </p>

                    {/* Descrição */}
                    <div className="border-t border-gray-100 pt-4 mb-4">
                        <p className="text-gray-700 text-sm leading-relaxed">{product.description}</p>
                    </div>

                    {/* Info */}
                    <div className="space-y-2 mb-5 text-sm">
                        <div className="flex items-center text-gray-500">
                            <FiMapPin className="mr-2 text-gray-400" size={14} />
                            <span>{product.location}</span>
                        </div>
                        <div className="flex items-center text-gray-500">
                            <FiUser className="mr-2 text-gray-400" size={14} />
                            <span>{product.sellerName}</span>
                        </div>
                        <div className="flex items-center text-gray-400 text-xs">
                            <FiEye className="mr-1" size={12} />
                            <span>{product.views || 0} visualizações</span>
                        </div>
                    </div>

                    {/* Contato */}
                    {!isOwner && (
                        <>
                            {showContact ? (
                                <div className="bg-green-50 rounded-xl p-4 border border-green-200">
                                    <p className="font-medium text-green-700 mb-1">{getContactMethodIcon(product.contactMethod)}</p>
                                    <p className="text-lg font-bold text-green-700">{product.contactNumber}</p>
                                    {product.contactHours && (
                                        <p className="text-xs text-green-600 mt-1">Horário: {product.contactHours}</p>
                                    )}
                                </div>
                            ) : (
                                <button
                                    onClick={() => {
                                        if (!user) {
                                            alert('Faça login para ver o contato');
                                            return;
                                        }
                                        setShowContact(true);
                                    }}
                                    className="w-full bg-blue-600 text-white py-2 rounded-lg font-medium hover:bg-blue-700 transition"
                                >
                                    Ver número do vendedor
                                </button>
                            )}
                        </>
                    )}

                    {isOwner && (
                        <div className="bg-blue-50 rounded-xl p-4 border border-blue-200">
                            <p className="text-blue-600 font-medium">📌 Este é seu anúncio</p>
                            <p className="text-sm text-blue-600 mt-1">
                                {getContactMethodIcon(product.contactMethod)}: {product.contactNumber}
                            </p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default ProductModal;
